package vn.iotstar.security; import lombok.RequiredArgsConstructor; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service; import vn.iotstar.repository.UserRepository; @Service @RequiredArgsConstructor public class CustomUserDetailsService implements UserDetailsService{private final UserRepository users;public UserDetails loadUserByUsername(String username){return users.findByUsername(username).map(CustomUserDetails::new).orElseThrow(()->new UsernameNotFoundException("Username không tồn tại"));}}